<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FinOps Dashboard — PT Borneo Prima</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body>
<header class="app-header"><img class="logo" src="/images/logo-bp.svg" alt="BP"><div class="brand"><b>PT BORNEO PRIMA</b><span>ACCOUNTING &amp; MINING COST DASHBOARD • LOCAL HOSTING (INTRANET)</span></div><button class="import">📥 Import GL<br><small>Data</small></button><div class="source-pill"><i></i>D365 GL:<br><span>Online</span></div><div class="source-pill"><i></i>Google Sheets:<br><span>Manual Sync</span></div><div class="period-label">Period:<b id="periodText">2026-10</b></div></header>
<div class="filterbar"><label>Month <input id="period" type="month" value="2026-10"></label><label>View <select id="mode"><option value="mtd">MTD</option><option value="ytd">YTD</option></select></label><span id="viewText">MTD — 2026-10</span></div>
<nav class="tabs"><a href="#" class="active" data-view="overview">📊 Executive Overview</a><a href="#" data-view="cost">📑 Report Cost (COGP)</a><a href="#" data-view="variance">📈 Cost Variance Analysis</a><a href="#" data-view="metric">⚖️ Cost per Metric Ton</a><a href="#" data-view="inventory">📦 Inventory Valuation (Moving Avg)</a><a href="#" data-view="financial">📑 Financial Statements (FS)</a><a href="#" data-view="integration">🔄 Integration &amp; Data Sources</a></nav>
<main class="content"><div class="heading"><h1>Operations &amp; Financial Overview</h1><p>Microsoft Dynamics 365 General Ledger and Google Sheets weighbridge data</p></div><section class="kpis"><article class="blue"><span>TOTAL ALL COST (GL)</span><strong id="allCost">—</strong><small>Costing to allocation, including Direct Expense (USD)</small><em>📁 gl_data.json · cost_report_history.json · accruals.json</em></article><article class="cyan"><span>TOTAL PRODUCTION VOLUME</span><strong>27,518 MT</strong><small>Coal mined weighbridge volume</small><em>📁 production_daily_sheets.json · production_data.json</em></article><article class="orange"><span>AVERAGE COST / MT</span><strong id="costPerMt">—</strong><small>Total operating cost / net MT</small><em>📁 gl_data.json · production_daily_sheets.json</em></article><article class="green"><span>TOTAL INVENTORY VALUE</span><strong>USD 16,439,149</strong><small>Provisional value — see quantity and cost sources</small><em>📁 inventory_model.json · inventory_movements.json</em></article><article class="blue"><span>GROSS PROFIT</span><strong>USD -</strong><small>Coal sales less cost of sales</small><em>📁 financial_baseline.json · gl_data.json</em></article><article class="blue"><span>OPERATING PROFIT / BEFORE INTEREST</span><strong id="expense">—</strong><small>Operating profit for the period</small><em>📁 financial_baseline.json · gl_data.json</em></article></section>
<section class="panel"><div class="panel-title"><h2>Production by Activity — Google Sheets DB</h2><span>📁 production_daily_sheets.json</span></div><div class="notice">Monthly figures use the DB sheet. Blank source cells are unavailable; YTD sums available months only. The daily chart below uses the Produksi sheet.</div><table><thead><tr><th>Activity</th><th>Volume</th><th>Unit</th><th>Availability</th></tr></thead><tbody><tr><td>Coal Getting</td><td>27,518</td><td>MT</td><td>Available</td></tr><tr><td>Hauling BUA to WP</td><td>7,313</td><td>MT</td><td>Available</td></tr><tr><td>Hauling BUA to Port</td><td>10,498</td><td>MT</td><td>Available</td></tr></tbody></table></section></main><footer>FinOps-Dashboard — PT Borneo Prima · Data freeze 2026-10-30</footer>
<script>const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(v||0));const title=document.querySelector('.heading h1'),subtitle=document.querySelector('.heading p'),panel=document.querySelector('.panel');async function load(view='overview'){const p=period.value,m=mode.value;periodText.textContent=p;viewText.textContent=`${m.toUpperCase()} — ${p}`;document.querySelectorAll('.tabs a').forEach(a=>a.classList.toggle('active',a.dataset.view===view));history.replaceState(null,'',`/?view=${view}&period=${p}&mode=${m}`);if(view==='inventory'){title.textContent='Inventory Valuation';subtitle.textContent='Provisional inventory quantity, value, and cost per MT';const r=await fetch(`/api/inventory-valuation?period=${p}`);if(!r.ok)return;const d=(await r.json()).data;panel.querySelector('.panel-title h2').textContent='Inventory stages';panel.querySelector('.panel-title span').textContent='📁 inventory_movements.json';panel.querySelector('.notice').textContent='Inventory valuation is provisional and follows the frozen workbook movement order.';panel.querySelector('tbody').innerHTML=(d.stages||[]).map(x=>`<tr><td>${x.name}</td><td>${x.rows.length} movement rows</td><td>—</td><td>Available</td></tr>`).join('');return}if(view!=='overview'&&view!=='cost'){title.textContent=document.querySelector(`[data-view="${view}"]`).textContent.trim();subtitle.textContent='Module tersedia pada API dan siap dihubungkan ke detail view.';panel.querySelector('.panel-title h2').textContent='Module status';panel.querySelector('.notice').textContent='Endpoint tersedia; detail table akan ditambahkan pada iterasi UI berikutnya.';panel.querySelector('tbody').innerHTML='<tr><td colspan="4">Pilih Executive Overview atau Report Cost untuk melihat data operasional.</td></tr>';return}title.textContent=view==='cost'?'Report Cost (COGP)':'Operations & Financial Overview';subtitle.textContent=view==='cost'?'Cost allocation by account and period':'Microsoft Dynamics 365 General Ledger and Google Sheets weighbridge data';const r=await fetch(`/api/cost-matrix?period=${p}&mode=${m}`);if(!r.ok)return;const d=(await r.json()).data;allCost.textContent=money(d.grandTotal.allCost);expense.textContent=`(${money(d.grandTotal.totalExpense)})`;costPerMt.textContent='USD —';panel.querySelector('.panel-title h2').textContent='Cost Matrix';panel.querySelector('.panel-title span').textContent=`${d.dataSource} · ${d.period}`;panel.querySelector('tbody').innerHTML=d.rows.filter(x=>!x.isParent).slice(0,30).map(x=>`<tr><td>${x.code}</td><td>${x.name}</td><td>${money(x.allCost)}</td><td>${money(x.totalCOGP)}</td><td>${money(x.totalExpense)}</td></tr>`).join('')}document.querySelectorAll('.tabs a').forEach(a=>a.onclick=e=>{e.preventDefault();load(a.dataset.view)});period.onchange=()=>load(document.querySelector('.tabs a.active').dataset.view);mode.onchange=()=>load(document.querySelector('.tabs a.active').dataset.view);load(new URLSearchParams(location.search).get('view')||'overview');</script></body></html>
